(function(){const G = window.__game, C = G.Col; const out = {}; const ps = C.items.filter((i) => i.k === 'p'), ks = C.items.filter((i) => i.k === 'k');
// wrong mode: foot standing on a pearl does nothing
G.Foot.on = true; G.Pl.x = ps[0].x; G.Pl.z = ps[0].z; G.Pl.y = 2; C.update(0.016, 1); out.footPearl = !!G.save.col.got[ps[0].id];
// boat collects pearls
const m0 = G.save.money; G.Foot.on = false; G.Boat.on = true; for (const p of ps) { G.Pl.x = p.x + 3; G.Pl.z = p.z; G.Pl.y = 0.3; C.update(0.016, 1); } G.Boat.on = false; out.pearls = ps.filter((p) => G.save.col.got[p.id]).length; out.pearlMoney = G.save.money - m0; out.prizeP = !!G.save.col.prize.p10;
// plane collects sparks
const m1 = G.save.money; G.Fly.on = true; for (const k of ks) { G.Pl.x = k.x + 5; G.Pl.z = k.z; G.Pl.y = k.y + 3; C.update(0.016, 1); } G.Fly.on = false; out.sparks = ks.filter((p) => G.save.col.got[p.id]).length; out.sparkMoney = G.save.money - m1; out.prizeK = !!G.save.col.prize.k10;
out.count = C.count(); const htm = C.pane(); out.paneLen = htm.length;
G.Foot.exit();
return JSON.stringify(out);})()
